    // The duel.dll RVA of a YuGiOh.exe function address, 0 when it has no known twin.
    inline uint32_t ToDuelRva(uintptr_t gameAddress)
    {
        if (gameAddress < 0x140000000 || gameAddress >= 0x150000000)
            return 0;
        const uint32_t rva = static_cast<uint32_t>(gameAddress - 0x140000000);
        const Pair* it = std::lower_bound(std::begin(kFunctions), std::end(kFunctions), rva, [](const Pair& p, uint32_t v) { return p.GameRva < v; });
        return it != std::end(kFunctions) && it->GameRva == rva ? it->DuelRva : 0;
    }
